+#!/usr/bin/env node
+const fs = require('fs');
+const path = require('path');
+const { execSync } = require('child_process');
+
+const worktrees = fs.readdirSync('.city-worktrees');
+const ages = worktrees.map(wt => {
+  const stat = fs.statSync(path.join('.city-worktrees', wt));
+  const ageHours = (Date.now() - stat.birthtimeMs) / (1000 * 60 * 60);
+  return { wt, ageHours };
+});
+
+ages.sort((a, b) => a.ageHours - b.ageHours);
+console.log('Worktree ages (oldest first):');
+ages.forEach(a => console.log(`${a.wt}: ${a.ageHours.toFixed(2)} hours`));
